const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  source.fileName ||
  args.fileName ||
  args.name ||
  message.text ||
  payload.text ||
  ''
).trim();

const folderId =
  source.folderId ||
  source.parentId ||
  args.folderId ||
  args.parentId ||
  payload.folderId ||
  'root';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function getExtension(fileName) {
  const match = String(fileName || '').match(/\.([a-z0-9]{1,12})$/i);
  return match ? match[1].toLowerCase() : '';
}

function mimeFromExtension(ext) {
  const map = {
    // text / note
    txt: 'text/plain',
    text: 'text/plain',
    log: 'text/plain',
    md: 'text/markdown',
    markdown: 'text/markdown',

    // data
    json: 'application/json',
    jsonl: 'application/x-ndjson',
    csv: 'text/csv',
    tsv: 'text/tab-separated-values',
    xml: 'application/xml',
    yaml: 'application/x-yaml',
    yml: 'application/x-yaml',
    toml: 'application/toml',
    ini: 'text/plain',
    env: 'text/plain',

    // web
    html: 'text/html',
    htm: 'text/html',
    css: 'text/css',
    js: 'application/javascript',
    mjs: 'application/javascript',
    ts: 'application/typescript',
    jsx: 'text/jsx',
    tsx: 'text/tsx',
    svg: 'image/svg+xml',

    // programming
    py: 'text/x-python',
    java: 'text/x-java-source',
    c: 'text/x-c',
    h: 'text/x-c',
    cpp: 'text/x-c++src',
    cc: 'text/x-c++src',
    cs: 'text/x-csharp',
    go: 'text/x-go',
    rs: 'text/rust',
    php: 'application/x-httpd-php',
    rb: 'text/x-ruby',
    swift: 'text/x-swift',
    kt: 'text/x-kotlin',
    sql: 'application/sql',
    r: 'text/x-r',
    lua: 'text/x-lua',

    // scripts/config
    sh: 'application/x-sh',
    bash: 'application/x-sh',
    zsh: 'application/x-sh',
    bat: 'application/x-msdos-program',
    cmd: 'application/x-msdos-program',
    ps1: 'text/plain',
    dockerfile: 'text/plain',
    gitignore: 'text/plain',

    // docs/binary phổ biến - chỉ hợp khi có binary upload thật
    pdf: 'application/pdf',
    doc: 'application/msword',
    docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    xls: 'application/vnd.ms-excel',
    xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    ppt: 'application/vnd.ms-powerpoint',
    pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',

    // image
    png: 'image/png',
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    gif: 'image/gif',
    webp: 'image/webp',

    // archive
    zip: 'application/zip',
    rar: 'application/vnd.rar',
    '7z': 'application/x-7z-compressed'
  };

  return map[ext] || 'text/plain';
}

function defaultExtensionForMime(mimeType) {
  const map = {
    'text/plain': 'txt',
    'text/markdown': 'md',
    'application/json': 'json',
    'text/csv': 'csv',
    'text/html': 'html',
    'text/css': 'css',
    'application/javascript': 'js',
    'application/typescript': 'ts',
    'text/x-python': 'py',
    'application/xml': 'xml',
    'application/x-yaml': 'yaml',
    'application/sql': 'sql',
    'image/svg+xml': 'svg'
  };

  return map[mimeType] || 'txt';
}

function isSafeTextMime(mimeType) {
  return [
    'text/plain',
    'text/markdown',
    'application/json',
    'application/x-ndjson',
    'text/csv',
    'text/tab-separated-values',
    'application/xml',
    'application/x-yaml',
    'application/toml',
    'text/html',
    'text/css',
    'application/javascript',
    'application/typescript',
    'text/jsx',
    'text/tsx',
    'image/svg+xml',
    'text/x-python',
    'text/x-java-source',
    'text/x-c',
    'text/x-c++src',
    'text/x-csharp',
    'text/x-go',
    'text/rust',
    'application/x-httpd-php',
    'text/x-ruby',
    'text/x-swift',
    'text/x-kotlin',
    'application/sql',
    'text/x-r',
    'text/x-lua',
    'application/x-sh',
    'application/x-msdos-program'
  ].includes(mimeType);
}

function parseCreateFile(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'tao file',
    'tao tep',
    'create file',
    'new file'
  ];

  let body = '';

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      body = original.slice(prefix.length + 1).trim();
      break;
    }

    if (normalized === prefix) {
      body = '';
      break;
    }
  }

  if (!body) {
    return {
      fileName: '',
      content: undefined
    };
  }

  const bodyNormalized = normalize(body);

  const contentMarkers = [
    ' noi dung ',
    ' content ',
    ' with content ',
    ' co noi dung '
  ];

  let splitIndex = -1;
  let markerLength = 0;

  for (const marker of contentMarkers) {
    const index = bodyNormalized.indexOf(marker);
    if (index !== -1) {
      splitIndex = index;
      markerLength = marker.length;
      break;
    }
  }

  if (splitIndex !== -1) {
    return {
      fileName: cleanName(body.slice(0, splitIndex)),
      content: body.slice(splitIndex + markerLength).replace(/^[:=\-\s]+/, '')
    };
  }

  return {
    fileName: cleanName(body),
    content: undefined
  };
}

const parsed = parseCreateFile(raw);

let fileName = cleanName(
  source.fileName ||
  source.name ||
  args.fileName ||
  args.name ||
  payload.fileName ||
  parsed.fileName
);

let content =
  source.content ??
  args.content ??
  payload.content ??
  parsed.content;

let mimeType =
  source.mimeType ||
  args.mimeType ||
  payload.mimeType ||
  '';

let ext = getExtension(fileName);

if (!mimeType && ext) {
  mimeType = mimeFromExtension(ext);
}

if (!mimeType) {
  mimeType = 'text/plain';
}

if (fileName && !ext) {
  const defaultExt = defaultExtensionForMime(mimeType);
  fileName += `.${defaultExt}`;
  ext = defaultExt;
}

const hasTarget = Boolean(fileName);

if (!fileName) {
  fileName = 'ghi-chu.txt';
  mimeType = 'text/plain';
}

const safeTextMime = isSafeTextMime(mimeType);

if (!safeTextMime) {
  return [{
    json: {
      ...source,
      payload,
      message,
      chatId,
      raw,
      rawText: raw,
      folderId,
      fileName,
      mimeType,
      content: '',
      hasTarget: false,
      response: [
        '⚠️ <b>Không nên tạo file rỗng dạng binary bằng lệnh này</b>',
        '',
        `File bạn yêu cầu: <code>${fileName}</code>`,
        `Loại: <code>${mimeType}</code>`,
        '',
        'Các định dạng như PDF, DOCX, XLSX, PPTX, ảnh, ZIP nên dùng:',
        '- upload file này vào drive',
        '- xuất file A sang pdf',
        '- tạo Google Docs/Sheets riêng',
        '',
        'Ví dụ tạo file text/code/data:',
        '<code>tạo file note.md nội dung # Ghi chú</code>',
        '<code>tạo file data.json nội dung {"name":"n8n"}</code>',
        '<code>tạo file table.csv nội dung name,age</code>'
      ].join('\n')
    }
  }];
}

content = String(content ?? '');

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    folderId,
    mimeType,
    fileName,
    content,
    extension: ext,
    hasTarget,
    response: hasTarget
      ? ''
      : '📄 <b>Tạo file</b>\n\nVí dụ:\n<code>tạo file ghi-chu.txt nội dung Xin chào</code>\n<code>tạo file data.json nội dung {"name":"n8n"}</code>',
  },
}];

const source = $('Prepare Action').item.json || {};

const content = String(source.content ?? '');
const mimeType = String(source.mimeType || 'text/plain');
const fileName = String(source.fileName || 'ghi-chu.txt');

return [{
  json: {
    ...source,
    binaryPropertyName: 'data',
    contentLength: content.length,
  },
  binary: {
    data: {
      data: Buffer.from(content, 'utf8').toString('base64'),
      mimeType,
      fileName,
    },
  },
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const source = $('Build File Binary').item.json || $('Prepare Action').item.json || {};
const item = $input.item.json || {};

const fileName = item.name || source.fileName || 'Không rõ tên';
const fileId = item.id || '';
const link =
  item.webViewLink ||
  item.webContentLink ||
  (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

const sizeLabel = Number.isFinite(Number(source.contentLength))
  ? `${Number(source.contentLength)} ký tự`
  : '';

const mimeType = source.mimeType || item.mimeType || '';

let text = '✅ <b>Đã tạo file trên Google Drive</b>\n\n';

text += `📄 <b>${escapeHtml(fileName)}</b>\n`;

if (mimeType) {
  text += `Loại: <code>${escapeHtml(mimeType)}</code>\n`;
}

if (fileId) {
  text += `ID: <code>${escapeHtml(fileId)}</code>\n`;
}

if (sizeLabel) {
  text += `Nội dung: ${escapeHtml(sizeLabel)}\n`;
}

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>`;
}

return [{
  json: {
    chatId: source.chatId,
    text: text.trim()
  }
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
